mapper.select:
SELECT COUNT(1)
FROM herb_image_match
WHERE image_id = #{imageId}

SELECT a.id AS atlas_id, a.atlas_no AS atlas_code, a.image_url AS atlas_image_url, a.species_id, s.herb_name AS species_name, f.feature_vector FROM herb_atlas a INNER JOIN herb_species s ON s.id = a.species_id AND s.is_deleted = 0 INNER JOIN herb_atlas_feature f ON f.atlas_id = a.id AND f.is_deleted = 0 AND f.extract_status = 'success' AND f.created_at = ( SELECT MAX(ff.created_at) FROM herb_atlas_feature ff WHERE ff.atlas_id = a.id AND ff.is_deleted = 0 AND ff.extract_status = 'success' ) WHERE a.is_deleted = 0 AND a.status = 1 AND f.feature_vector IS NOT NULL AND f.feature_vector != ''
AND a.species_id = #{speciesId}
ORDER BY a.id ASC

SELECT
FROM herb_image_match m INNER JOIN herb_image i ON i.id = m.image_id AND i.is_deleted = 0 INNER JOIN herb_atlas a ON a.id = m.atlas_id AND a.is_deleted = 0 LEFT JOIN herb_species s ON s.id = a.species_id AND s.is_deleted = 0
ORDER BY m.created_at DESC, m.match_rank ASC LIMIT #{offset}, #{pageSize}
